"""Build the offline accessible video review page from the real capture's telemetry."""
from pathlib import Path
import json
out=Path('docs/validation/clubhouse-fidelity');trace=json.loads((out/'trace-match.json').read_text());samples=[{'ms':s['ms'],'feet':s['players'][0]['feet'],'camera':s['camera']} for s in trace['samples']];marks=trace['marks'];move=marks[0]['ms']/1000;stop=marks[1]['ms']/1000
html='''<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>HoopSim — fidélité Clubhouse</title><style>body{margin:0;background:#f3e8d0;color:#173e2d;font:17px/1.5 system-ui}main{max-width:1420px;margin:auto;padding:24px}h1{font-size:30px}a{color:#174c34}button{font:inherit;background:#173e2d;color:#fff3d4;padding:10px 16px;border:0;border-radius:4px;cursor:pointer}button:focus-visible,a:focus-visible{outline:3px solid #da8d0d;outline-offset:3px}.player{display:grid;grid-template-columns:minmax(0,1fr) minmax(250px,390px);gap:20px;align-items:start}video{width:100%;background:#142d27}canvas{width:100%;height:auto;image-rendering:pixelated;border:1px solid #53765a}nav{display:flex;flex-wrap:wrap;gap:10px;margin:18px 0}figure{margin:0}figcaption{font-size:14px}img{display:block;width:100%;height:auto}details{margin-top:20px}footer{border-top:1px solid;margin-top:30px;font-size:14px}@media(max-width:850px){.player{grid-template-columns:1fr}.loupe{max-width:390px}}</style><main><h1>HoopSim — contrôle de fidélité Clubhouse</h1><p>Vrai match de la carrière Boston, #45 Andre Fifita. Ordre : dribble sur place → déplacement → arrêt. La loupe affiche les pixels de cette même vidéo, agrandis ×4.</p><div class="player"><figure><video id="video" controls preload="metadata" playsinline aria-describedby="description"><source src="45-dribble-deplacement-arret.mp4" type="video/mp4"><track kind="captions" src="45-dribble.vtt" srclang="fr" label="Étapes du parcours" default></video><figcaption id="description">Caméra normale du match. Capture sans accélération, sans bande sonore. Après l’arrêt, les pieds se stabilisent et le dribble continue sur place.</figcaption></figure><figure class="loupe"><canvas id="loupe" width="512" height="512" aria-label="Loupe du #45, agrandissement commun par pixels"></canvas><figcaption>Loupe ×4. Aucun redessin ni interpolation.</figcaption></figure></div><nav aria-label="Étapes de la vidéo"><button onclick="seek(0)">1. Sur place</button><button onclick="seek(MOVE)">2. Déplacement</button><button onclick="seek(STOP)">3. Arrêt</button><button id="rate" onclick="v.playbackRate=v.playbackRate===1?.5:1;this.textContent=v.playbackRate===1?'Lecture ×1':'Inspection ×0,5'">Lecture ×1</button><a href="45-dribble-deplacement-arret.mp4" download>Télécharger le MP4</a></nav><p><output id="stage" aria-live="polite">Dribble sur place</output></p><details open><summary>Comparaison du #45 — même pose, orientation et échelle</summary><img src="comparaison-45.png" alt="Référence et match : #45 debout, trois-quarts face vers la droite, échelle commune, loupe quatre fois."><p>Le recadrage du match conserve le parquet, l’ombre et le cercle de sélection. Aucun redimensionnement indépendant des silhouettes. <a href="comparaison-echelle.json">Mesures du cadrage</a>.</p></details><details><summary>Portrait — référence et jeu</summary><img src="comparaison-portrait.png" alt="Portraits du #45 à la même échelle sur fond clair."></details><details><summary>Franchise — maquette et interface jouable</summary><img src="comparaison-franchise.png" alt="Maquette à gauche, interface de la carrière à droite, même fenêtre de 1672 par 941 pixels."></details><footer>Les boutons Contrat, Rotation et Préparer le match restent reliés aux parcours de management existants. Le joueur, les règles et les résultats de simulation sont conservés. Voir le bilan livré dans l’archive.</footer></main><script>const MOVE=__MOVE__,STOP=__STOP__,samples=__SAMPLES__,v=document.getElementById('video'),c=document.getElementById('loupe'),ctx=c.getContext('2d');ctx.imageSmoothingEnabled=false;let current='';function seek(t){v.currentTime=t;v.play()}function draw(){if(v.readyState>=2){let s=samples.reduce((a,b)=>Math.abs(b.ms-v.currentTime*1000)<Math.abs(a.ms-v.currentTime*1000)?b:a);let x=(s.feet.x-s.camera.left)*s.camera.screenZoom,y=(s.feet.y-s.camera.top)*s.camera.screenZoom;ctx.drawImage(v,Math.round(x-64),Math.round(y-112),128,128,0,0,512,512);let label=v.currentTime< MOVE?'Dribble sur place':v.currentTime<STOP?'Dribble en déplacement':'Arrêt — appuis stabilisés, dribble sur place';if(current!==label){document.getElementById('stage').value=label;current=label}}requestAnimationFrame(draw)}draw();</script></html>'''.replace('__MOVE__',str(move)).replace('__STOP__',str(stop)).replace('__SAMPLES__',json.dumps(samples,separators=(',',':')))
(out/'index.html').write_text(html)
def ts(t):return f'{int(t)//3600:02}:{int(t)//60%60:02}:{int(t)%60:02}.{int(t%1*1000):03}'
end=trace['samples'][-1]['ms']/1000
(out/'45-dribble.vtt').write_text('WEBVTT\n\n'+''.join(f'{ts(a)} --> {ts(b)}\n{label}\n\n' for a,b,label in [(0,move,'Dribble sur place'),(move,stop,'Dribble en déplacement'),(stop,end,'Arrêt : appuis stabilisés et dribble sur place')]))
print('Lecteur hors ligne : chapitres, sous-titres et loupe synchronisée ×4.')
